#!/usr/bin/env node
/**
 * Builds the TEST `needs-attention` Edge Function deploy artifact from the committed
 * source (see TEST-ENV.md "Finance Foundation - F8a", Deploy; same method as finance).
 *
 *   node scripts/build-needs-attention-bundle.mjs          # (re)write the artifact + manifest
 *   node scripts/build-needs-attention-bundle.mjs --check  # rebuild in memory; exit 1 if the
 *                                                  # committed artifact/manifest differ
 *
 * Input:  supabase/functions-test/needs-attention/*.ts (entry index.ts) plus the
 *         allowlisted pure Finance modules (SHARED_FINANCE_FILES, F8b).
 * Output: supabase/deploy-artifacts/needs-attention/index.js     (the one file deployed)
 *         supabase/deploy-artifacts/needs-attention/manifest.json (provenance)
 *
 * Deterministic: esbuild is pinned (package.json, exact version) and every
 * option is fixed here; no timestamps, paths or environment values go into
 * the output. The only import left external is the jsr: registry import of
 * supabase-js that the source already declares (resolved by Supabase at
 * deploy time, exactly as before); nothing is fetched from GitHub.
 * The artifact is never edited by hand.
 */
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { build, version } from "esbuild";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC_DIR = join(ROOT, "supabase/functions-test/needs-attention");
const OUT_DIR = join(ROOT, "supabase/deploy-artifacts/needs-attention");
const ARTIFACT = "index.js";
/**
 * Finance F8b: the ONLY files from outside the needs-attention folder the
 * bundle may contain - Finance's pure F2-F6 modules (no fetch, no Deno, no
 * writes), so invoice_draft_blocked reviews drafts with Finance's own code.
 * F16 adds F13's and F15's pure modules for the Money Out rules.
 * They are bundled at build time (never a runtime import of another Edge
 * Function), listed in the manifest with their hashes, and covered by
 * --check: any change to one of them changes this artifact.
 */
export const SHARED_FINANCE_FILES = [
  "finance-billing-mapping.ts",
  "finance-billing.ts",
  "finance-commercial-mapping.ts",
  "finance-commercial.ts",
  "finance-effective-dating.ts",
  "finance-invoicing-mapping.ts",
  "finance-invoicing.ts",
  "finance-issue-mapping.ts",
  "finance-issue.ts",
  "finance-lifecycle.ts",
  "finance-money.ts",
  "finance-settings.ts",
  // F16 Money Out rules: F13's instalment lifecycle (remainingOf / stateOf) and F15's employment month line.
  "finance-overheads.ts",
  "finance-suppliers.ts",
];
const FINANCE_DIR = join(ROOT, "supabase/functions-test/finance");
const PINNED_ESBUILD = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")).devDependencies.esbuild;

const OPTIONS = {
  entryPoints: [join(SRC_DIR, "index.ts")],
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2022",
  external: ["jsr:*"],
  minify: true,
  lineLimit: 160,
  legalComments: "none",
  charset: "utf8",
  sourcemap: false,
  metafile: true,
  write: false,
  logLevel: "warning",
};

const sha256 = (b) => createHash("sha256").update(b).digest("hex");

async function make() {
  if (version !== PINNED_ESBUILD) throw new Error(`esbuild ${version} is installed but package.json pins ${PINNED_ESBUILD} - run npm ci`);
  const sources = readdirSync(SRC_DIR)
    .filter((f) => f.endsWith(".ts"))
    .sort()
    .map((f) => ({ path: relative(ROOT, join(SRC_DIR, f)), sha256: sha256(readFileSync(join(SRC_DIR, f))) }))
    .concat(SHARED_FINANCE_FILES.map((f) => ({ path: relative(ROOT, join(FINANCE_DIR, f)), sha256: sha256(readFileSync(join(FINANCE_DIR, f))) })));
  const sourceSha256 = sha256(sources.map((s) => `${s.path}\0${s.sha256}\n`).join(""));
  const res = await build(OPTIONS);
  const bundled = Object.keys(res.metafile.inputs).map((p) => relative(ROOT, join(ROOT, p))).sort();
  const listed = sources.map((s) => s.path);
  const unused = listed.filter((p) => !bundled.includes(p));
  const foreign = bundled.filter((p) => !listed.includes(p));
  if (foreign.length) throw new Error(`bundle pulled in files outside ${relative(ROOT, SRC_DIR)} and the shared Finance allowlist: ${foreign.join(", ")}`);
  const banner = `// needs-attention (TEST) deploy artifact - GENERATED by scripts/build-needs-attention-bundle.mjs (esbuild ${version}) from supabase/functions-test/needs-attention + ${SHARED_FINANCE_FILES.length} shared Finance modules (source sha256 ${sourceSha256}). Do not edit.\n`;
  const code = banner + Buffer.from(res.outputFiles[0].contents).toString("utf8");
  if (/raw\.githubusercontent\.com|https?:\/\/[^"'`\s]*github/i.test(code)) throw new Error("artifact must not import anything from GitHub");
  const imports = [...new Set(Object.values(res.metafile.outputs).flatMap((o) => o.imports.filter((i) => i.external).map((i) => i.path)))].sort();
  if (imports.some((i) => !i.startsWith("jsr:"))) throw new Error(`unexpected external import(s): ${imports.join(", ")}`);
  const manifest = {
    function: "needs-attention",
    project: "TEST only",
    artifact: `supabase/deploy-artifacts/needs-attention/${ARTIFACT}`,
    artifactSha256: sha256(code),
    artifactBytes: Buffer.byteLength(code),
    entrypoint: ARTIFACT,
    externalImports: imports,
    esbuild: version,
    options: { ...OPTIONS, entryPoints: ["supabase/functions-test/needs-attention/index.ts"], write: undefined, metafile: undefined },
    sourceSha256,
    sources,
    unusedSources: unused,
  };
  return { code, manifest: JSON.stringify(manifest, null, 2) + "\n" };
}

const { code, manifest } = await make();
if (process.argv.includes("--check")) {
  let ok = true;
  for (const [name, want] of [[ARTIFACT, code], ["manifest.json", manifest]]) {
    let have = "";
    try {
      have = readFileSync(join(OUT_DIR, name), "utf8");
    } catch {}
    const same = have === want;
    ok &&= same;
    console.log(`${same ? "MATCH" : "DIFF "} supabase/deploy-artifacts/needs-attention/${name} ${sha256(want)}`);
  }
  if (!ok) {
    console.log("The committed needs-attention artifact is not what the committed source builds to - run node scripts/build-needs-attention-bundle.mjs");
    process.exit(1);
  }
} else {
  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, ARTIFACT), code);
  writeFileSync(join(OUT_DIR, "manifest.json"), manifest);
  console.log(`wrote supabase/deploy-artifacts/needs-attention/${ARTIFACT} (${Buffer.byteLength(code)} bytes, sha256 ${sha256(code)})`);
}
